import{_ as e,o as r,c as a,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"手机端 App","description":"","frontmatter":{},"headers":[],"relativePath":"basic/mobile.md","filePath":"basic/mobile.md","lastUpdated":1792319529000}'),o={name:"basic/mobile.md"};function i(l,t,h,n,s,b){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="手机端-app" tabindex="-1">手机端 App <a class="header-anchor" href="#手机端-app" aria-label="Permalink to &quot;手机端 App&quot;">​</a></h1><p>手机客户端源码在独立仓库 <a href="https://github.com/Zero-wyc/ZViewerAPP" target="_blank" rel="noreferrer">ZViewerAPP</a>。界面与播放器随安装包分发，应用内填写服务端地址即可连接。</p><p>客户端连接的是你自己的 ZViewer 服务端，账号、房间与权限均由服务端决定；媒体来源与可用功能同样取决于服务端与所在平台。</p><h2 id="支持的平台" tabindex="-1">支持的平台 <a class="header-anchor" href="#支持的平台" aria-label="Permalink to &quot;支持的平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>最低版本</th></tr></thead><tbody><tr><td>Android</td><td>7.0 / API 24</td></tr><tr><td>HarmonyOS</td><td>6.1 / API 23</td></tr></tbody></table><p>两端都只提供 64 位版本。</p><h2 id="获取安装包" tabindex="-1">获取安装包 <a class="header-anchor" href="#获取安装包" aria-label="Permalink to &quot;获取安装包&quot;">​</a></h2><p>从 <a href="https://github.com/Zero-wyc/ZViewerAPP/releases" target="_blank" rel="noreferrer">ZViewerAPP Releases</a> 下载；每个版本同时附源码压缩包与 <code>SHA256SUMS.txt</code>，可用于校验完整性。</p><table tabindex="0"><thead><tr><th>平台</th><th>安装包</th></tr></thead><tbody><tr><td>Android</td><td><code>ZViewer-Android-&lt;版本号&gt;-release.apk</code></td></tr><tr><td>HarmonyOS</td><td><code>ZViewer-HarmonyOS-&lt;版本号&gt;-release.hap</code></td></tr><tr><td>源码</td><td><code>ZViewer-client-&lt;版本号&gt;-source.zip</code></td></tr></tbody></table><h2 id="连接服务器" tabindex="-1">连接服务器 <a class="header-anchor" href="#连接服务器" aria-label="Permalink to &quot;连接服务器&quot;">​</a></h2><ol><li>启动应用，在连接页填入 ZViewer 服务端地址。</li><li>用服务端账号登录；服务端允许游客时也可游客身份进入。</li><li>进入房间大厅，选择房间加入。</li></ol><p>能否建房取决于服务端设置：限制为仅管理员时，手机端也只能加入他人房间。</p><h2 id="功能差异" tabindex="-1">功能差异 <a class="header-anchor" href="#功能差异" aria-label="Permalink to &quot;功能差异&quot;">​</a></h2><p>手机端与网页版共用业务代码，房间、片单、弹幕、字幕、音乐与语音行为一致，差异集中在平台能力。</p><table tabindex="0"><thead><tr><th>能力</th><th>手机端</th><th>网页版</th></tr></thead><tbody><tr><td>同步观影、片单、聊天、弹幕、字幕</td><td>支持</td><td>支持</td></tr><tr><td>一起听音乐</td><td>支持，窄屏重排，平板保留多列</td><td>支持</td></tr><tr><td>房间语音</td><td>支持，可申请麦克风、静音、查看成员状态</td><td>支持</td></tr><tr><td>观看他人屏幕共享</td><td>支持</td><td>支持</td></tr><tr><td>发起屏幕共享</td><td>不支持（无屏幕采集能力）</td><td>支持，需 HTTPS</td></tr><tr><td>B 站高画质</td><td>内置扫码登录与本机播放代理</td><td>需 <a href="/basic/cli">ZViewer CLI</a></td></tr><tr><td>系统播放控件</td><td>原生媒体会话，支持通知控制与后台播放</td><td>由浏览器决定</td></tr><tr><td>屏幕旋转</td><td>顶栏旋转按钮，全屏时播放器内另有入口</td><td>由设备与浏览器决定</td></tr></tbody></table><p>切换标签页、收起面板或更换房间模式都不会结束语音通话。</p><h2 id="内置-b-站登录与画质" tabindex="-1">内置 B 站登录与画质 <a class="header-anchor" href="#内置-b-站登录与画质" aria-label="Permalink to &quot;内置 B 站登录与画质&quot;">​</a></h2><p>两端均内置 B 站扫码登录与本机播放代理，无需另装 ZViewer CLI。登录后自动选择账号有权限、视频有实际轨道且设备支持的最高普通画质，并排除 HDR 与杜比视界。</p><p>最高画质播放失败时有限恢复一次，仍失败则回退 720P，再不行退到更低可用档位。手动选择的画质按影片记住，房主与观众各自在本机生效。</p><p>B 站 Cookie 在 Android 上经 Keystore 加密后存入不可备份目录；画质广播不包含本机代理地址与凭据。</p><h2 id="播放手势" tabindex="-1">播放手势 <a class="header-anchor" href="#播放手势" aria-label="Permalink to &quot;播放手势&quot;">​</a></h2><p>原生播放器在捕获阶段接管视频表面的触屏操作，桌面网页手势不变。</p><ul><li>单击视频表面只唤出控件，不切换播放状态。</li><li>一起看：双击画面中间三分之一切换播放 / 暂停。</li><li>一起看全屏：双击左三分之一后退 15 秒，双击右三分之一前进 15 秒，范围限制在 0 到时长之间。</li><li>一起听：仅纯净模式的全屏视频启用同一套手势。全屏单击唤出退出按钮，3 秒后自动隐藏，也可用 Esc 或系统返回键退出。</li></ul><h2 id="后台播放" tabindex="-1">后台播放 <a class="header-anchor" href="#后台播放" aria-label="Permalink to &quot;后台播放&quot;">​</a></h2><p>两端均接入系统媒体会话，锁屏与通知栏显示影片 / 歌曲信息、播放状态与解码后的封面，支持系统播放、暂停、跳转与可用时的切歌。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>提示无法覆盖安装</strong> — 多为包名或签名与已装版本不一致。先记录服务器地址与个人设置再卸载（会清除本地数据）；调试版与正式版包名不同，可并存。</p><p><strong>画质上不到最高档</strong> — 先确认 B 站账号在该视频能选到该清晰度，再确认设备能解码该编码。HDR 与杜比视界被自动排除属预期行为。</p><p><strong>手机无法发起屏幕共享</strong> — 手机端不提供屏幕采集，只能观看他人共享，需要发起时请用网页版。</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="https://github.com/Zero-wyc/ZViewerAPP" target="_blank" rel="noreferrer">ZViewerAPP 仓库</a> · <a href="https://github.com/Zero-wyc/ZViewerAPP/releases" target="_blank" rel="noreferrer">下载安装包</a></li><li><a href="https://github.com/Zero-wyc/ZViewerAPP/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">更新记录</a> · <a href="https://github.com/Zero-wyc/ZViewerAPP/blob/main/PORTING.md" target="_blank" rel="noreferrer">跨平台移植说明</a></li></ul>',31)])])}const P=e(o,[["render",i]]);export{p as __pageData,P as default};
